        return a.compareTo(b) >= 0 ? a : b;
    }
}

import java.util.*;

class GenericsDemo {
    // bounded type parameter: T phai so sanh duoc
    static <T extends Comparable<T>> T max(List<? extends T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) best = item;
        }
        return best;
    }

    // consumer: chi ghi -> super
    static void addNumbers(List<? super Integer> sink) {
        sink.add(1);
        sink.add(2);
    }

    public static void main(String[] args) {
        List<Integer> ints = new ArrayList<>(List.of(3, 9, 4));
        System.out.println(max(ints));            // 9

        List<? extends Number> readOnly = ints;
        System.out.println(readOnly.get(0));      // doc: OK
        // readOnly.add(5);                        // LOI: khong biet kieu chinh xac -> khong ghi duoc

        List<Number> sink = new ArrayList<>();
        addNumbers(sink);                          // Number la super cua Integer
        System.out.println(sink);                  // [1, 2]
    }
}

import java.util.*;

class CollectionsDemo {
    // record: tu dong sinh equals/hashCode dung hop dong -> khoa an toan
    record CustomerId(String value) {}

    public static void main(String[] args) {
        Map<CustomerId, Integer> orders = new HashMap<>();
        orders.put(new CustomerId("C1"), 3);
        // instance khac nhau nhung equals -> tim duoc
        System.out.println(orders.get(new CustomerId("C1")));   // 3

        // API tien dung thay cho if-else quanh get()
        orders.merge(new CustomerId("C1"), 2, Integer::sum);     // 5
        orders.computeIfAbsent(new CustomerId("C2"), k -> 0);
        System.out.println(orders.getOrDefault(new CustomerId("C9"), -1)); // -1

        // List.of tra ve danh sach BAT BIEN
        List<String> fixed = List.of("a", "b");
        try {
            fixed.add("c");
        } catch (UnsupportedOperationException e) {
            System.out.println("immutable: " + e.getClass().getSimpleName());
        }

        // Xoa an toan khi dang duyet: removeIf, khong phai for-each + remove
        List<String> names = new ArrayList<>(List.of("an", "binh", "chi"));
        names.removeIf(n -> n.length() <= 2);
        System.out.println(names);   // [binh, chi]
    }
}

class InsufficientBalanceException extends Exception {
    InsufficientBalanceException(String message) {
        super(message);
    }
}

class InvalidAmountException extends RuntimeException {
    InvalidAmountException(String message) {
        super(message);
    }
}

class Account {
    private double balance;

    Account(double balance) {
        this.balance = balance;
    }

    void withdraw(double amount) throws InsufficientBalanceException {
        if (amount <= 0) {
            throw new InvalidAmountException("amount must be positive");
        }
        if (amount > balance) {
            throw new InsufficientBalanceException("not enough balance");
        }
        balance -= amount;
    }
}

class ExceptionDemo {
    static class OrderNotFoundException extends RuntimeException {
        private final String orderId;
        OrderNotFoundException(String orderId, Throwable cause) {
            super("Order not found: " + orderId, cause);   // GIU nguyen nhan goc
            this.orderId = orderId;
        }
        String getOrderId() { return orderId; }
    }

    static String loadRaw(String id) {
        throw new IllegalStateException("db timeout");        // loi tang ha tang
    }

    static String findOrder(String id) {
        try {
            return loadRaw(id);
        } catch (IllegalStateException e) {
            throw new OrderNotFoundException(id, e);          // dich sang loi domain
        }
    }

    public static void main(String[] args) {
        try {
            findOrder("A-1");
        } catch (OrderNotFoundException e) {
            System.out.println(e.getMessage());
            System.out.println("root cause: " + e.getCause().getMessage());
        }
    }
}

import java.util.ArrayList;
import java.util.List;

class LogBuffer implements AutoCloseable {
    private final List<String> lines = new ArrayList<>();
    private boolean closed = false;

    void write(String line) {
        lines.add(line);
    }

    List<String> lines() {
        return lines;
    }

    boolean isClosed() {
        return closed;
    }

    @Override
    public void close() {
        closed = true;
    }
}

class MultiResourceDemo {
    void run() {
        try (LogBuffer first = new LogBuffer();
             LogBuffer second = new LogBuffer()) {
            first.write("a");
            second.write("b");
        }
    }
}

class TwrDemo {
    static class Res implements AutoCloseable {
        private final String name;
        Res(String name) { this.name = name; System.out.println("open " + name); }
        void use() { throw new IllegalStateException("loi trong than try"); }
        @Override public void close() {
            System.out.println("close " + name);
            throw new IllegalStateException("loi khi close " + name);
        }
    }

    public static void main(String[] args) {
        try (Res a = new Res("A"); Res b = new Res("B")) {   // dong B truoc, roi A
            a.use();
        } catch (Exception e) {
            System.out.println("chinh: " + e.getMessage());
            for (Throwable s : e.getSuppressed()) {
                System.out.println("suppressed: " + s.getMessage());
            }
        }
    }
}

